function extractXSRFTokenFromCookie(){var e=document.cookie.split("; ").find(e=>e.startsWith("BRS-XSRF-TOKEN="));return e?e.split("=")[1]:null}function setXSRFRequestHeader(e){e.setRequestHeader("X-BRS-XSRF-TOKEN",extractXSRFTokenFromCookie())}function decodeHtmlAsString(e){var t=document.createElement("textarea");return t.innerHTML=e,t.value}function EscapeHtml(e){return e.replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}function umsSettingsInherit(e,t,a){t?e?($(a).attr("disabled",!0),$("#sender-user-name").attr("disabled","disabled"),$("#mail-password").attr("disabled","disabled")):$(a).attr("disabled",!1):e?($(a).addClass("disabled"),$("#sender-user-name").attr("disabled","disabled"),$("#mail-password").attr("disabled","disabled")):$(a).removeClass("disabled")}$.ajaxSetup({beforeSend:function(e){setXSRFRequestHeader(e)}});
